namespace ShipmentTracker.Client.Services;

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public DateTime CreatedAt { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string? CustomerEmail { get; set; }
    public string Description { get; set; } = string.Empty;
}

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<ShipmentDto>> GetAllShipmentsAsync();
    Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<List<ShipmentDto>> GetMyShipmentsAsync();
    Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment);
    Task UpdateShipmentStatusAsync(int id, string status);
}

using System.Net.Http.Json;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService(HttpClient httpClient) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
        => await httpClient.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? [];

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
        => await httpClient.GetFromJsonAsync<ShipmentDto?>($"api/shipments/track/{trackingNumber}");

    public async Task<List<ShipmentDto>> GetMyShipmentsAsync()
        => await httpClient.GetFromJsonAsync<List<ShipmentDto>>("api/shipments/my") ?? [];

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment)
    {
        var response = await httpClient.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<ShipmentDto>() ?? shipment;
    }

    public async Task UpdateShipmentStatusAsync(int id, string status)
    {
        var response = await httpClient.PutAsJsonAsync($"api/shipments/{id}/status", new { Status = status });
        response.EnsureSuccessStatusCode();
    }
}

using Microsoft.AspNetCore.Http;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db, IHttpContextAccessor httpContextAccessor) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => MapToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment is null ? null : MapToDto(shipment);
    }

    public async Task<List<ShipmentDto>> GetMyShipmentsAsync()
    {
        var userEmail = httpContextAccessor.HttpContext?.User?.Identity?.Name;
        if (string.IsNullOrEmpty(userEmail))
            return [];

        return await db.Shipments
            .Where(s => s.CustomerEmail == userEmail)
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => MapToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment)
    {
        var entity = new Shipment
        {
            TrackingNumber = shipment.TrackingNumber,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = Enum.TryParse<ShipmentStatus>(shipment.Status, out var status) ? status : ShipmentStatus.Pending,
            CreatedAt = DateTime.UtcNow,
            EstimatedDelivery = shipment.EstimatedDelivery,
            CustomerEmail = shipment.CustomerEmail,
            Description = shipment.Description
        };

        db.Shipments.Add(entity);
        await db.SaveChangesAsync();

        return MapToDto(entity);
    }

    public async Task UpdateShipmentStatusAsync(int id, string status)
    {
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is null) return;

        if (Enum.TryParse<ShipmentStatus>(status, out var newStatus))
        {
            shipment.Status = newStatus;
            await db.SaveChangesAsync();
        }
    }

    private static ShipmentDto MapToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status.ToString(),
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        CustomerEmail = s.CustomerEmail,
        Description = s.Description
    };
}

