@page "/dispatcher/shipments"
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<div class="container mt-4">
    <div class="d-flex justify-content-between align-items-center mb-3">
        <h2>📋 Shipment Management</h2>
        <a href="dispatcher/shipments/create" class="btn btn-success">+ New Shipment</a>
    </div>

    <div class="row mb-3">
        <div class="col-md-4">
            <input type="text" class="form-control" placeholder="Filter by destination..."
                   @bind="filterDestination" @bind:event="oninput" />
        </div>
        <div class="col-md-4">
            <select class="form-select" @bind="filterStatus">
                <option value="">All Statuses</option>
                <option value="Pending">Pending</option>
                <option value="PickedUp">Picked Up</option>
                <option value="InTransit">In Transit</option>
                <option value="OutForDelivery">Out For Delivery</option>
                <option value="Delivered">Delivered</option>
                <option value="Exception">Exception</option>
            </select>
        </div>
        <div class="col-md-4">
            <button class="btn btn-outline-secondary" @onclick="LoadShipments">Refresh</button>
        </div>
    </div>

    @if (isLoading)
    {
        <p><em>Loading shipments...</em></p>
    }
    else if (errorMessage is not null)
    {
        <div class="alert alert-danger">@errorMessage</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Created</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var shipment in FilteredShipments)
                    {
                        <tr>
                            <td><strong>@shipment.TrackingNumber</strong></td>
                            <td>@shipment.Origin</td>
                            <td>@shipment.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                            <td>@shipment.CreatedAt.ToString("MMM dd, yyyy")</td>
                            <td>@(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "N/A")</td>
                            <td>
                                <select class="form-select form-select-sm d-inline-block w-auto"
                                        @onchange="(e) => UpdateStatus(shipment.Id, e.Value?.ToString() ?? string.Empty)">
                                    <option value="">Update...</option>
                                    <option value="Pending">Pending</option>
                                    <option value="PickedUp">Picked Up</option>
                                    <option value="InTransit">In Transit</option>
                                    <option value="OutForDelivery">Out For Delivery</option>
                                    <option value="Delivered">Delivered</option>
                                    <option value="Exception">Exception</option>
                                </select>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
        <p class="text-muted">Showing @FilteredShipments.Count of @shipments.Count shipments</p>
    }
</div>

@code {
    private List<ShipmentDto> shipments = [];
    private bool isLoading = true;
    private string? errorMessage;
    private string filterDestination = string.Empty;
    private string filterStatus = string.Empty;

    private List<ShipmentDto> FilteredShipments => shipments
        .Where(s => string.IsNullOrEmpty(filterDestination) || s.Destination.Contains(filterDestination, StringComparison.OrdinalIgnoreCase))
        .Where(s => string.IsNullOrEmpty(filterStatus) || s.Status == filterStatus)
        .ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task UpdateStatus(int id, string status)
    {
        if (string.IsNullOrEmpty(status)) return;
        try
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, status);
            await LoadShipments();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to update status: {ex.Message}";
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-warning text-dark",
        "OutForDelivery" => "bg-primary",
        "Delivered" => "bg-success",
        "Exception" => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/dispatcher/shipments/create"
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Create Shipment</PageTitle>

<div class="container mt-4">
    <h2>📦 Create New Shipment</h2>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="alert alert-danger">@errorMessage</div>
    }

    <div class="card mt-3">
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label">Tracking Number</label>
                <input type="text" class="form-control" @bind="shipment.TrackingNumber" placeholder="e.g., SHP-008-XYZ" />
            </div>
            <div class="row mb-3">
                <div class="col-md-6">
                    <label class="form-label">Origin</label>
                    <input type="text" class="form-control" @bind="shipment.Origin" placeholder="City, State" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Destination</label>
                    <input type="text" class="form-control" @bind="shipment.Destination" placeholder="City, State" />
                </div>
            </div>
            <div class="mb-3">
                <label class="form-label">Description</label>
                <input type="text" class="form-control" @bind="shipment.Description" placeholder="Package description" />
            </div>
            <div class="row mb-3">
                <div class="col-md-6">
                    <label class="form-label">Customer Email</label>
                    <input type="email" class="form-control" @bind="shipment.CustomerEmail" placeholder="customer@example.com" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Estimated Delivery</label>
                    <input type="date" class="form-control" @bind="estimatedDelivery" />
                </div>
            </div>
            <div class="mb-3">
                <label class="form-label">Status</label>
                <select class="form-select" @bind="shipment.Status">
                    <option value="Pending">Pending</option>
                    <option value="PickedUp">Picked Up</option>
                    <option value="InTransit">In Transit</option>
                    <option value="OutForDelivery">Out For Delivery</option>
                    <option value="Delivered">Delivered</option>
                </select>
            </div>
            <div class="d-flex gap-2">
                <button class="btn btn-primary" @onclick="CreateShipment" disabled="@isSubmitting">
                    @(isSubmitting ? "Creating..." : "Create Shipment")
                </button>
                <a href="dispatcher/shipments" class="btn btn-outline-secondary">Cancel</a>
            </div>
        </div>
    </div>
</div>

@code {
    private ShipmentDto shipment = new() { Status = "Pending" };
    private DateTime? estimatedDelivery;
    private bool isSubmitting;
    private string? errorMessage;

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(shipment.TrackingNumber) ||
            string.IsNullOrWhiteSpace(shipment.Origin) ||
            string.IsNullOrWhiteSpace(shipment.Destination))
        {
            errorMessage = "Tracking number, origin, and destination are required.";
            return;
        }

        try
        {
            isSubmitting = true;
            errorMessage = null;
            shipment.EstimatedDelivery = estimatedDelivery;
            await ShipmentService.CreateShipmentAsync(shipment);
            Navigation.NavigateTo("dispatcher/shipments");
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create shipment: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

@page "/my-shipments"
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>My Shipments</PageTitle>

<div class="container mt-4">
    <h2>📦 My Shipments</h2>

    @if (isLoading)
    {
        <p><em>Loading your shipments...</em></p>
    }
